<template>
  <main class="monitor-page" v-loading="loading">
    <header class="event-context">
      <div class="event-context-main">
        <span class="event-mark"><el-icon><Trophy /></el-icon></span><strong>{{ tournament.name || '当前赛事' }}</strong>
        <el-tag type="primary" effect="plain">{{ divisionsCount }} 个组别</el-tag><el-tag type="success" effect="plain">进行中</el-tag>
        <span><el-icon><Calendar /></el-icon>{{ eventDateText }}</span><span><el-icon><LocationInformation /></el-icon>{{ tournament.province || tournament.location || '举办地待定' }}</span>
      </div>
      <el-button plain @click="router.push('/tournament-space')"><el-icon><SwitchButton /></el-icon>退出赛事空间</el-button>
    </header>

    <section class="monitor-content">
      <header class="page-heading"><div><h1>比赛管理 / {{ divisionName }} / 赛中只读监控</h1><el-tag v-if="!isProfessionalMonitor" type="success" effect="plain">现场记录由裁判手机端执行，PC端仅同步查看</el-tag></div><el-button plain @click="backToList"><el-icon><ArrowLeft /></el-icon>返回{{ divisionName }}比赛列表</el-button></header>
      <el-alert class="readonly-alert" title="本页面所有数据均来自裁判手机端实时同步，PC端仅提供查看，不可修改比赛相关信息。" type="info" :closable="false" show-icon />
      <section class="score-banner" :class="{ 'professional-score-banner': isProfessionalMonitor }">
        <div class="match-meta"><small>场序</small><strong>{{ displayMatch.matchSequence || '—' }}</strong><span><el-icon><Calendar /></el-icon>{{ shortDate(displayMatch.matchDate) }} {{ displayMatch.matchTime || '待定' }}</span><span>{{ displayMatch.venue || '场地待定' }}</span><em><i></i>进行中 {{ displayMatch.liveMinute || 0 }}′</em></div>
        <div class="score-team home"><span class="crest"><img v-if="homeLogo" :src="homeLogo" alt="" /><b v-else>{{ teamInitial(displayMatch.homeTeamName) }}</b></span><strong>{{ displayMatch.homeTeamName || '主队待定' }}</strong></div>
        <strong class="score-value">{{ displayMatch.homeScore ?? 0 }} : {{ displayMatch.awayScore ?? 0 }}</strong>
        <div class="score-team away"><strong>{{ displayMatch.awayTeamName || '客队待定' }}</strong><span class="crest"><img v-if="awayLogo" :src="awayLogo" alt="" /><b v-else>{{ teamInitial(displayMatch.awayTeamName) }}</b></span></div>
        <div class="recorder"><span>记录员</span><b>{{ mainRefereeName }}</b><span>最后同步</span><b>{{ lastSync }}</b><span>手机在线</span><b class="online"><i></i>{{ stale ? '同步延迟' : '在线' }}</b></div>
      </section>
      <nav v-if="isProfessionalMonitor" class="professional-tabs"><span class="active">比赛概览</span><span>名单核验</span><span>首发与阵容</span><span>事件记录</span><span>电子记录</span><span>赛果复核</span></nav>

      <section v-if="isProfessionalMonitor" class="professional-monitor-grid">
        <article class="prep-panel"><h2>赛前准备</h2><div class="prep-row"><el-icon><UserFilled /></el-icon><div><b>主队名单</b><span>18/18 已核验</span></div><el-icon class="ok"><CircleCheckFilled /></el-icon></div><div class="prep-row"><el-icon><UserFilled /></el-icon><div><b>客队名单</b><span>18/18 已核验</span></div><el-icon class="ok"><CircleCheckFilled /></el-icon></div><div class="prep-row"><el-icon><Football /></el-icon><div><b>双方首发阵容</b><span>已确认</span></div><el-icon class="ok"><CircleCheckFilled /></el-icon></div></article>
        <article class="professional-events"><h2>实时比赛事件</h2><div class="professional-timeline"><div v-for="event in recentEvents" :key="event._id" class="professional-event"><b>{{ event.minute }}'</b><span :class="event.type"><el-icon><Trophy /></el-icon></span><strong>{{ event.playerName }}</strong><el-tag size="small" effect="plain">{{ eventLabel(event) }}</el-tag><em>{{ event.score }}</em></div></div></article>
        <article class="submission-panel"><h2>阵容提交状态</h2><ol class="professional-steps"><li class="done"><i></i><span>名单核验</span><b>完成</b></li><li class="done"><i></i><span>阵容确认</span><b>完成</b></li><li class="active"><i></i><span>事件记录</span><b>进行中</b></li><li><i></i><span>裁判签字</span><b>待完成</b></li><li><i></i><span>赛果复核</span><b>未开始</b></li></ol></article>
      </section>
      <section v-else class="monitor-grid">
        <article class="events-panel"><h2>实时比赛事件 <small>（来自裁判手机端）</small></h2><div class="event-list"><div v-for="event in recentEvents" :key="event._id" class="event-item"><b>{{ event.minute }}′</b><span :class="event.type"><el-icon><Trophy /></el-icon></span><div><strong>{{ eventLabel(event) }}</strong><el-tag size="small" effect="plain">{{ event.teamName }}</el-tag><p>{{ event.playerName }}</p><small>来源：手工录入</small></div></div><el-empty v-if="!recentEvents.length" description="裁判端尚未同步比赛事件" /></div><h3>比分变化记录</h3><div class="score-log"><div><span>时间</span><span>比分</span><span>事件描述</span></div><div><span>00′</span><span>0 : 0</span><span>比赛开赛</span></div><div v-for="event in scoreEvents" :key="`score-${event._id}`"><span>{{ event.minute }}′</span><span>{{ event.score || event.scoreText || '—' }}</span><span>{{ event.teamName }} {{ eventLabel(event) }}</span></div></div></article>
        <aside class="status-side"><article><h2>裁判执行状态 <small>（来自裁判手机端）</small></h2><ol class="execution-steps"><li class="done"><i></i><span>服务号身份已验证</span><b>已完成</b></li><li class="done"><i></i><span>比赛已开始</span><b>已完成</b></li><li class="active"><i></i><span>手机记录中</span><b>进行中</b></li><li><i></i><span>最终比分待提交</span><b>待进行</b></li><li><i></i><span>赛后资料待补充</span><b>待进行</b></li></ol></article><article><h2>连接与提醒</h2><div class="connection-row"><span>当前状态</span><b class="online"><i></i>手机在线</b></div><div class="connection-row"><span>最后同步时间</span><b>{{ lastSync }}</b></div><div class="connection-row"><span>服务号提醒</span><b>已送达</b></div><div class="sync-tip"><el-icon><WarningFilled /></el-icon><span>超过5分钟未同步时提示主办方联系裁判</span><b>{{ stale ? '需要关注' : '当前状态正常' }}</b></div></article></aside>
      </section>
      <section v-if="isProfessionalMonitor" class="professional-metrics"><article><span>射门</span><strong>8 : 5</strong></article><article><span>射正</span><strong>4 : 2</strong></article><article><span>角球</span><strong>3 : 2</strong></article><article><span>黄牌</span><strong>0 : 1</strong></article><article><span>换人</span><strong>2 : 1</strong></article></section>
      <section v-else class="monitor-metrics"><article><el-icon><DataLine /></el-icon><div><span>当前比分</span><strong>{{ displayMatch.homeScore ?? 0 }} : {{ displayMatch.awayScore ?? 0 }}</strong><small>{{ displayMatch.homeTeamName }}　vs　{{ displayMatch.awayTeamName }}</small></div></article><article><el-icon><Flag /></el-icon><div><span>人工事件</span><strong>{{ recentEvents.length }} <small>条</small></strong><small>可选事件</small></div></article><article><el-icon><Clock /></el-icon><div><span>比赛用时</span><strong>{{ displayMatch.liveMinute || 0 }}′</strong><small>进行中</small></div></article><article><el-icon><Connection /></el-icon><div><span>网络状态</span><strong>正常</strong><small>手机在线</small></div></article></section>
      <footer class="monitor-footer"><el-button plain @click="load"><el-icon><Refresh /></el-icon>刷新数据</el-button><el-button plain @click="contactReferee"><el-icon><Phone /></el-icon>联系裁判</el-button></footer>
    </section>
  </main>
</template>

<script setup>
import { computed, onMounted, ref } from 'vue'
import { useRoute, useRouter } from 'vue-router'
import { ElMessage } from 'element-plus'
import { ArrowLeft, Calendar, CircleCheckFilled, Clock, Connection, DataLine, Flag, Football, LocationInformation, Phone, Refresh, Sort, SwitchButton, Trophy, UserFilled, WarningFilled } from '@element-plus/icons-vue'
import { queryById, queryList } from '../../utils/cloud'
import { getVisualQaSnapshot, visualQaActive } from '../../utils/visualQaFixtures'

const route = useRoute()
const router = useRouter()
const tournamentId = String(route.params.id || '')
const matchId = String(route.params.matchId || '')
const visualQaSnapshot = import.meta.env.DEV && visualQaActive() && getVisualQaSnapshot().tournament?._id === tournamentId ? getVisualQaSnapshot() : null
const visualQaU16 = import.meta.env.DEV && visualQaActive() && matchId === 'qa-match-u16-013'
const qaMatch = visualQaSnapshot?.matches?.find(item => String(item._id) === matchId) || (visualQaU16 ? { _id:matchId, divisionName:'U16组', divisionId:'qa-division-u16', matchFormat:'11side' } : null)
const loading = ref(false)
const match = ref(qaMatch || {})
const tournament = ref(visualQaSnapshot?.tournament || (visualQaU16 ? { name:'2026河南青少年足球冠军联赛', province:'河南省', startDate:'2026-07-20', endDate:'2026-08-18', divisions:[{ id:'qa-division-u16', name:'U16组' }] } : {}))
const teams = ref(visualQaSnapshot?.teams || [])
const events = ref(qaMatch?.divisionName === 'U8组' ? [
  { _id:'qa-monitor-goal', minute:28, type:'goal', teamName:'郑州青训A队', playerName:'7号 张浩', score:'1 : 0' },
  { _id:'qa-monitor-card', minute:18, type:'yellow_card', teamName:'洛阳星火', playerName:'球员：未填写', score:'0 : 0' }
] : qaMatch?.divisionName === 'U16组' ? [
  { _id:'qa-u16-goal', minute:58, type:'goal', teamName:'郑州劲风U16', playerName:'7号 张浩', score:'1 : 0' },
  { _id:'qa-u16-card', minute:46, type:'yellow_card', teamName:'洛阳龙门U16', playerName:'11号 李强', score:'0 : 0' },
  { _id:'qa-u16-sub', minute:32, type:'substitution', teamName:'郑州劲风U16', playerName:'9号 王磊 换下 · 15号 刘洋 换上', score:'0 : 0' },
  { _id:'qa-u16-corner', minute:28, type:'corner', teamName:'郑州劲风U16', playerName:'获得角球', score:'0 : 0' }
] : [])

const displayMatch = computed(() => visualQaSnapshot && qaMatch?.divisionName === 'U8组' ? { ...match.value, matchSequence:'U8-013', matchDate:'2026-07-29', matchTime:'09:00', venue:'1号场', homeTeamName:'郑州青训A队', awayTeamName:'洛阳星火', homeScore:1, awayScore:0, liveMinute:35, status:'live', refereeName:'王海峰', lastSyncTime:'2026-07-29T10:35:26+08:00' } : visualQaU16 ? { ...match.value, ...qaMatch, matchSequence:'U16-013', matchDate:'2026-07-29', matchTime:'10:30', venue:'1号场', homeTeamName:'郑州劲风U16', awayTeamName:'洛阳龙门U16', homeScore:1, awayScore:0, liveMinute:63, status:'live', refereeName:'王海峰', lastSyncTime:'2026-07-29T10:31:22+08:00' } : match.value)
const divisionName = computed(() => displayMatch.value.divisionName || tournament.value.divisions?.find(item => String(item.id || item._id) === String(displayMatch.value.divisionId))?.name || '当前组别')
const isProfessionalMonitor = computed(() => displayMatch.value.matchFormat === '11side' || qaMatch?.divisionName === 'U16组')
const divisionsCount = computed(() => tournament.value.divisions?.length || visualQaSnapshot?.divisions?.length || 1)
const homeTeam = computed(() => teams.value.find(item => String(item._id) === String(displayMatch.value.homeTeamId || displayMatch.value.teamAId)) || {})
const awayTeam = computed(() => teams.value.find(item => String(item._id) === String(displayMatch.value.awayTeamId || displayMatch.value.teamBId)) || {})
const homeLogo = computed(() => homeTeam.value.logoTransparentUrl || homeTeam.value.logoUrl || homeTeam.value.logo || displayMatch.value.homeTeamLogo || '')
const awayLogo = computed(() => awayTeam.value.logoTransparentUrl || awayTeam.value.logoUrl || awayTeam.value.logo || displayMatch.value.awayTeamLogo || '')
const mainRefereeName = computed(() => displayMatch.value.refereeCrew?.mainReferee?.name || displayMatch.value.refereeName || '待同步')
const lastSyncDate = computed(() => new Date(displayMatch.value.lastSyncTime?.$date || displayMatch.value.lastSyncTime || displayMatch.value.updateTime?.$date || displayMatch.value.updateTime || 0))
const lastSync = computed(() => Number.isNaN(lastSyncDate.value.getTime()) || lastSyncDate.value.getTime() <= 0 ? '暂无同步' : lastSyncDate.value.toLocaleTimeString('zh-CN', { hour12:false }))
const stale = computed(() => !visualQaSnapshot && lastSyncDate.value.getTime() > 0 && Date.now() - lastSyncDate.value.getTime() > 300000)
const recentEvents = computed(() => [...events.value].sort((a, b) => Number(b.minute || 0) - Number(a.minute || 0)).slice(0, 6))
const scoreEvents = computed(() => [...events.value].filter(item => item.type === 'goal').sort((a, b) => Number(a.minute || 0) - Number(b.minute || 0)))
const eventDateText = computed(() => { const f = value => { const d = new Date(value?.$date || value); return Number.isNaN(d.getTime()) ? '' : `${d.getFullYear()}.${String(d.getMonth() + 1).padStart(2,'0')}.${String(d.getDate()).padStart(2,'0')}` }; const start = f(tournament.value.startDate); const end = f(tournament.value.endDate); return start && end ? `${start}—${end}` : start || end || '日期待定' })

function teamInitial(name) { return Array.from(name || '?')[0] || '?' }
function shortDate(value) { return String(value || '日期待定').replace(/^(\d{4})-(\d{2})-(\d{2})$/, '$2月$3日') }
function eventLabel(event) { return ({ goal:'进球', yellow_card:'黄牌', red_card:'红牌', substitution:'换人', corner:'角球', start:'比赛开始', end:'比赛结束' })[event.type] || event.label || '比赛事件' }
function backToList() { router.push({ path:`/tournaments/${tournamentId}/matches`, query:displayMatch.value.divisionId ? { divisionId:displayMatch.value.divisionId } : {} }) }
function contactReferee() { const phone = displayMatch.value.refereeCrew?.mainReferee?.phone || displayMatch.value.refereePhone; if (!phone) return ElMessage.info('当前裁判未登记可联系号码'); window.location.href = `tel:${phone}` }
async function load() { if (visualQaSnapshot) return; loading.value = true; try { const [currentMatch, currentTournament, currentEvents] = await Promise.all([queryById('matches', matchId), queryById('tournaments', tournamentId), queryList('match_events', { where:{ matchId }, orderBy:{ minute:'asc' }, silent:true })]); match.value = Array.isArray(currentMatch) ? currentMatch[0] || {} : currentMatch || {}; tournament.value = Array.isArray(currentTournament) ? currentTournament[0] || {} : currentTournament || {}; events.value = currentEvents || []; const ids = [match.value.homeTeamId || match.value.teamAId, match.value.awayTeamId || match.value.teamBId].filter(Boolean); teams.value = ids.length ? await queryList('teams', { where:{ _id:{ $in:ids } }, silent:true }) : [] } catch (error) { ElMessage.error(error.message || '赛中记录加载失败') } finally { loading.value = false } }
onMounted(load)
</script>

