nd:#087637;border-color:#087637}.execution-steps li.active i{border-color:#087637;box-shadow:inset 0 0 0 3px #fff;background:#087637}.execution-steps b{font-size:14px;font-weight:400}.connection-row{display:flex;justify-content:space-between;min-height:29px}.connection-row span{color:#69746e}.sync-tip{display:grid;grid-template-columns:25px 1fr auto;align-items:center;gap:7px;margin-top:9px;padding:11px;border:1px solid #ffbf80;border-radius:5px;color:#ff7a06;background:#fff9f2}.sync-tip b{font-size:14px}.monitor-metrics{display:grid;grid-template-columns:repeat(4,1fr);gap:28px;margin-top:16px}.monitor-metrics article{display:flex;align-items:center;justify-content:center;gap:23px;min-height:94px;border:1px solid #e1e7e3;border-radius:8px;background:#fff}.monitor-metrics article>.el-icon{font-size:44px;color:#087237}.monitor-metrics span,.monitor-metrics small{display:block;color:#66726b}.monitor-metrics strong{display:block;margin:4px 0;font-size:28px}.monitor-metrics strong small{display:inline;color:#17251c;font-size:15px}.monitor-footer{display:flex;justify-content:center;gap:44px;margin-top:18px}.monitor-footer .el-button{width:282px;height:47px;color:#2f3f35;border-color:#adb7b0;font-size:17px}@media(max-width:1180px){.score-banner{grid-template-columns:220px 1fr 120px 1fr}.recorder{display:none}.monitor-grid{grid-template-columns:1fr}.monitor-metrics{gap:12px}.page-heading>div{align-items:flex-start;flex-direction:column;gap:8px}}@media(max-width:760px){.event-context{padding:12px 16px}.event-context-main>span:not(.event-mark){display:none}.monitor-content{padding:18px 16px}.page-heading{align-items:flex-start;flex-direction:column;gap:12px}.page-heading h1{font-size:26px}.score-banner{grid-template-columns:1fr 1fr;gap:14px;padding:18px}.match-meta{grid-column:1/-1;border:0}.score-value{grid-column:1/-1;grid-row:2}.score-team{grid-row:3}.monitor-metrics{grid-template-columns:1fr 1fr}.monitor-footer{gap:12px}.monitor-footer .el-button{width:calc(50% - 6px)}.sc